css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .62); position: relative; }
.loader .hull { position: absolute; left: 16%; top: 42%; width: 68%; height: 18%; border-radius: 46% 8% 8% 46% / 60% 40% 40% 60%; background: linear-gradient(var(--accent-2), var(--accent)); animation: row-glide calc(var(--loader-speed) * 1.6) ease-in-out infinite; }
.loader .oar { position: absolute; left: 48%; top: 45%; width: 42%; height: 5%; border-radius: 3px; background: linear-gradient(90deg, #cbd5e1, #64748b); transform-origin: 3% 50%; }
.loader .oar::after { content: ''; position: absolute; left: 82%; top: -70%; width: 22%; height: 240%; border-radius: 40%; background: var(--accent); }
.loader .oar:nth-of-type(1) { animation: row-stroke calc(var(--loader-speed) * 1.6) ease-in-out infinite; }
.loader .oar:nth-of-type(2) { animation: row-stroke-mirror calc(var(--loader-speed) * 1.6) ease-in-out infinite; }
.loader .wave { position: absolute; left: 2%; right: 2%; bottom: 12%; height: 8%; border-radius: 4px; background: repeating-linear-gradient(90deg, color-mix(in srgb, var(--accent) 45%, transparent) 0 14%, transparent 0 28%); animation: row-water calc(var(--loader-speed) * 1.6) linear infinite; }
@keyframes row-stroke { 0%, 100% { transform: rotate(-36deg); } 50% { transform: rotate(-4deg); } }
@keyframes row-stroke-mirror { 0%, 100% { transform: rotate(36deg); } 50% { transform: rotate(4deg); } }
@keyframes row-glide { 0%, 100% { transform: translateX(0); } 50% { transform: translateX(-5%); } }
@keyframes row-water { to { background-position: -28% 0; } }
